import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';

export default function TeacherQuestionBank({ userName, teacherGrades, timetable }) {
  const [bankQuestions, setBankQuestions] = useState([]);
  
  // 🟢 ඩේටාබේස් එකේ timetable දත්ත ගබඩා කරගැනීමට අලුතින් එක් කළ State එක
  const [dbTimetable, setDbTimetable] = useState([
    { id: 1, grade: 'Grade 9', subject: 'Mathematics', teacher: 'Charaka Dikwella' },
    { id: 2, grade: 'Grade 10', subject: 'Mathematics', teacher: 'Charaka Dikwella' },
    { id: 4, grade: 'Grade 6', subject: 'Mathematics', teacher: 'Buddhika Darshani' }, 
    { id: 5, grade: 'Grade 7', subject: 'Mathematics', teacher: 'Buddhika Darshani' }, 
    { id: 6, grade: 'Grade 8', subject: 'Mathematics', teacher: 'Buddhika Darshani' }, 
    { id: 7, grade: 'Grade 6', subject: 'Science', teacher: 'Ravindu Jayaweera' }
  ]);
  
  // Form States
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');

  // 🟢 FIXED: 8082 පෝට් එක හරහා ඩේටාබේස් එකෙන් ලයිව්ම ප්‍රශ්න සහ කාලසටහන ලබාගැනීම
  const refreshBank = () => {
    axiosInstance.get('http://localhost:8082/api/get-bank')
      .then(res => setBankQuestions(Array.isArray(res.data) ? res.data : []))
      .catch(() => {
        const saved = localStorage.getItem('aura_central_question_bank');
        setBankQuestions(saved ? JSON.parse(saved) : []);
      });

    axiosInstance.get('http://localhost:8082/api/timetable')
      .then(res => {
        if (Array.isArray(res.data)) setDbTimetable(res.data);
      })
      .catch(() => {});
  };

  useEffect(() => { 
    refreshBank(); 
  }, []);

  // 🟢 RELATIONAL LOGIC: ලොග් වී සිටින ටීචර්ට උගන්වන්න අදාළ ශ්‍රේණි සහ විෂයන් පමණක් වෙන් කරගැනීම
  const myTimeSlots = dbTimetable.filter(t => t.teacher === userName);
  
  const availableGrades = myTimeSlots.length > 0 
    ? [...new Set(myTimeSlots.map(t => t.grade))]
    : ['Grade 6', 'Grade 7', 'Grade 8'];
  
  const availableSubjects = myTimeSlots.length > 0
    ? [...new Set(myTimeSlots.map(t => t.subject))]
    : ['Mathematics'];

  const [selectedGrade, setSelectedGrade] = useState('Grade 8');
  const [selectedSubject, setSelectedSubject] = useState('Mathematics');

  // කාලසටහන් දත්ත ලෝඩ් වුණු වහාම Dropdowns වල ඩිෆෝල්ට් අගයන් සකස් කිරීම
  useEffect(() => {
    if (availableGrades.length > 0) setSelectedGrade(availableGrades[0]);
    if (availableSubjects.length > 0) setSelectedSubject(availableSubjects[0]);
  }, [dbTimetable]);

  const handleAddToBank = (e) => {
    e.preventDefault();
    const payload = {
      question_text: qText,
      option_a: optA, 
      option_b: optB, 
      option_c: optC, 
      option_d: optD,
      correct_option: correctOpt,
      grade: selectedGrade,
      subject: selectedSubject,
      teacher_name: userName
    };

    // 🟢 FIXED: 8082 පෝට් එක හරහා සැබෑ MySQL ඩේටාබේස් එකටම දත්ත සේව් කිරීම
    axiosInstance.post('http://localhost:8082/api/add-to-bank', payload)
      .then(res => {
        if (res.data.status === "Success") {
          alert("✅ Question Saved Successfully to Database Repository!");
          clearForm(); 
          refreshBank();
        }
      })
      .catch(() => {
        // සර්වර් එකේ ගැටලුවක් වුවහොත් පමණක් LocalStorage එකට සේව් වේ (Fallback Backup)
        const currentBank = JSON.parse(localStorage.getItem('aura_central_question_bank')) || [];
        const updatedBank = [{ id: Date.now(), ...payload }, ...currentBank];
        localStorage.setItem('aura_central_question_bank', JSON.stringify(updatedBank));
        setBankQuestions(updatedBank);
        alert("✅ Question Saved (Offline Backup Mode)!");
        clearForm();
      });
  };

  const clearForm = () => {
    setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A');
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      <div>
        <h2 style={{ color: '#1e293b', margin: 0 }}>📚 Central Question Bank Repository</h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          විෂය සහ ශ්‍රේණිය වෙන වෙනම තෝරාගෙන පද්ධතියේ ප්‍රධාන ප්‍රශ්න බැංකුවට ප්‍රශ්න එකතු කිරීමේ ද්වාරය.
        </p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
        
        {/* LEFT COMPONENT: ADD QUESTION FORM */}
        <div style={styles.card('#6b21a8')}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '16px', color: '#1e293b' }}>➕ Add New Question Matrix</h3>
          <form onSubmit={handleAddToBank} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            
            {/* 🟢 DYNAMIC DROPDOWNS: දැන් මෙතන ටීචර්ට අදාළ දත්ත පමණක් පෙන්වයි */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
              <div>
                <label style={styles.label}>Select Target Grade</label>
                <select value={selectedGrade} onChange={e => setSelectedGrade(e.target.value)} style={styles.fullInput}>
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div>
                <label style={styles.label}>Select Target Subject</label>
                <select value={selectedSubject} onChange={e => setSelectedSubject(e.target.value)} style={styles.fullInput}>
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div>
              <label style={styles.label}>Question Text (ප්‍රශ්න විස්තරය)</label>
              <textarea placeholder="Type the question here..." value={qText} onChange={e => setQText(e.target.value)} required style={{ ...styles.fullInput, height: '60px', resize: 'none' }} />
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <label style={styles.label}>MCQ Choices & Correct Key Indicator</label>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} name="bank_ans" /> <input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} name="bank_ans" /> <input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} name="bank_ans" /> <input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} name="bank_ans" /> <input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.fullInput} /></div>
            </div>

            <button type="submit" style={{ ...styles.btn, backgroundColor: '#6b21a8', padding: '12px', marginTop: '5px' }}>
              💾 Save Inside Central Repository Bank
            </button>
          </form>
        </div>

        {/* RIGHT COMPONENT: BANK ARCHIVE WITH FILTER LABELS */}
        <div style={styles.card('#475569')}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '16px', color: '#1e293b' }}>📚 Repository Archive List ({bankQuestions.length})</h3>
          
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '440px', overflowY: 'auto', paddingRight: '5px' }}>
            {bankQuestions.length > 0 ? (
              bankQuestions.map((q, idx) => (
                <div key={q.id || idx} style={{ backgroundColor: '#f8fafc', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '6px' }}>
                    <span style={{ color: '#64748b', fontWeight: 'bold' }}>Q-Ref #{idx + 1}</span>
                    <div style={{ display: 'flex', gap: '5px' }}>
                      <span style={{ color: '#2563eb', backgroundColor: '#dbeafe', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold' }}>{q.subject}</span>
                      <span style={{ color: '#16a34a', backgroundColor: '#dcfce7', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold' }}>{q.grade}</span>
                    </div>
                  </div>
                  <h4 style={{ margin: '0 0 8px 0', fontSize: '14px', color: '#1e293b' }}>{q.question_text}</h4>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '5px', fontSize: '12px', color: '#475569', paddingLeft: '10px' }}>
                    <div>A) {q.option_a}</div>
                    <div>B) {q.option_b}</div>
                    <div>C) {q.option_c}</div>
                    <div>D) {q.option_d}</div>
                  </div>
                  <div style={{ fontSize: '11px', color: '#16a34a', fontWeight: 'bold', marginTop: '8px', borderTop: '1px dashed #e2e8f0', paddingTop: '6px' }}>
                    🔑 Answer Key Indicator: Option ({q.correct_option}) | Created by: {q.teacher_name || 'System Teacher'}
                  </div>
                </div>
              ))
            ) : (
              <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '13px', fontStyle: 'italic', padding: '30px' }}>
                📭 ප්‍රශ්න බැංකුව හිස්ව පවතී. වම් පසින් ඔබේම ප්‍රශ්න ඇතුළත් කරන්න.
              </p>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  fullInput: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box' },
  btn: { color: 'white', border: 'none', padding: '11px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13.5px' },
  label: { display: 'block', fontSize: '11.5px', fontWeight: 'bold', color: '#475569', marginBottom: '4px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '10px', width: '100%' }
};
